# Generated by curate-skills
# Workflow: corvallis_winter_weather_comparison
# Function: process_weather_variable

import csv
import os
import tempfile
from datetime import date

import pandas as pd

RANK_VARIABLES = {1: "PRCP", 2: "TMIN", 3: "TMAX"}
UNITS = {"PRCP": "mm", "TMIN": "degC", "TMAX": "degC"}
THIS_YEAR = 2025
THIS_START = date(2025, 1, 1)
THIS_END = date(2025, 3, 1)
BASE_YEARS = list(range(2015, 2025))  # previous 10 winters


def _season_month_days():
    """Calendar days Dec 02 .. Mar 31 in season order, including Feb 29."""
    days = [f"12-{d:02d}" for d in range(2, 32)]
    days += [f"01-{d:02d}" for d in range(1, 32)]
    days += [f"02-{d:02d}" for d in range(1, 30)]
    days += [f"03-{d:02d}" for d in range(1, 32)]
    return days


def _season_date(winter_year, month_day):
    """Actual date of a month-day within the winter ending in winter_year, or None if invalid."""
    month, day = int(month_day[:2]), int(month_day[3:])
    year = winter_year - 1 if month == 12 else winter_year
    try:
        return date(year, month, day)
    except ValueError:
        return None


def process_weather_variable(folder: str, input1: str, output1: str) -> None:
    r = faasr_rank()
    rank = int(r["rank"])
    if rank not in RANK_VARIABLES:
        msg = f"ERROR: unexpected rank {rank}; expected 1..3"
        faasr_log(msg)
        raise ValueError(msg)
    var = RANK_VARIABLES[rank]
    units = UNITS[var]
    in_name = input1.format(rank=rank) if "{rank}" in input1 else input1
    out_name = output1.format(rank=rank)
    faasr_log(f"Rank {rank}: processing {var} from {in_name}")

    tmpdir = tempfile.mkdtemp()
    local_in = os.path.join(tmpdir, "station.csv")
    faasr_get_file(local_file=local_in, remote_folder=folder, remote_file=in_name)
    if not os.path.exists(local_in) or os.path.getsize(local_in) == 0:
        msg = f"ERROR: input {in_name} is missing or empty"
        faasr_log(msg)
        raise RuntimeError(msg)

    df = pd.read_csv(local_in, dtype=str, keep_default_na=False)
    for col in ("DATE", var):
        if col not in df.columns:
            msg = f"ERROR: column {col} not found in {in_name}"
            faasr_log(msg)
            raise RuntimeError(msg)

    dates = pd.to_datetime(df["DATE"].str.strip(), format="%Y-%m-%d", errors="coerce")
    raw = df[var].str.strip()
    values = pd.to_numeric(raw.where(raw != ""), errors="coerce") / 10.0
    series = pd.Series(values.values, index=dates.dt.date.values)
    series = series[pd.notna(series.index)].dropna()
    series = series[~series.index.duplicated(keep="first")]
    lookup = series.to_dict()
    faasr_log(f"{var}: {len(lookup)} non-missing daily values in station record")

    rows = []
    n_this = 0
    for md in _season_month_days():
        vals = []
        for wy in BASE_YEARS:
            d = _season_date(wy, md)
            if d is not None and d in lookup:
                vals.append(lookup[d])
        avg = round(sum(vals) / len(vals), 4) if vals else ""

        this_d = _season_date(THIS_YEAR, md)
        this_date_str, this_val = "", ""
        if this_d is not None and THIS_START <= this_d <= THIS_END:
            this_date_str = this_d.isoformat()
            if this_d in lookup:
                this_val = round(lookup[this_d], 4)
                n_this += 1
        rows.append([var, md, this_date_str, this_val, avg, len(vals), units])

    faasr_log(f"{var}: {n_this} values in {THIS_START}..{THIS_END}; {len(rows)} season rows")
    if n_this == 0 and all(row[4] == "" for row in rows):
        msg = f"ERROR: no {var} data found for the requested windows"
        faasr_log(msg)
        raise RuntimeError(msg)

    local_out = os.path.join(tmpdir, "result.csv")
    with open(local_out, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["variable", "month_day", "this_year_date", "this_year_value",
                    "ten_year_avg", "n_years", "units"])
        w.writerows(rows)

    faasr_put_file(local_file=local_out, remote_folder=folder, remote_file=out_name)
    faasr_log(f"Uploaded {out_name}")
